function renderHome(){const done=Object.keys(state.answers).length,hasSave=state.started;mount(`<section class="landing"><div class="landing-main"><div class="landing-copy"><p class="eyebrow">AN INTERACTIVE LOVE STORY · 十二幕恋爱故事</p><h1>与你，<br><em>未完待续。</em></h1><p class="landing-lead">从第一次约会，到毕业后的两座城市。<br>周屿和林初夏的下一幕，交给你来选择。</p><div class="landing-actions"><button class="button-primary" data-action="${hasSave?'continue':'start'}">${hasSave?'继续我们的故事':'翻开故事'}${icon('arrow')}</button>${hasSave?'<button class="text-button" data-action="restart">重新开始</button>':'<button class="text-button" data-action="how">怎么玩</button>'}</div><p class="landing-meta">${hasSave?`已走过 ${done} / 12 幕 · 上次停在第 ${state.cursor+1} 幕`:'12 个情境 · 由你选择的后续 · 一份专属恋爱报告'}</p></div><div class="cover-collage" id="cover-collage"><div class="collage-orbit"></div><figure class="photo-card photo-main">${picture('q02-A',{eager:true,sizes:'(max-width:760px) 85vw, 50vw'})}<figcaption><span>心动，是每一次靠近</span><span>Chapter 02</span></figcaption></figure><figure class="photo-card photo-small">${picture('q10-B',{eager:true,sizes:'(max-width:760px) 45vw, 30vw'})}<figcaption><span>下一幕，与你</span><span>To be continued</span></figcaption></figure><div class="cover-stamp"><b>12</b>moments<br>of us</div><div class="cover-star">${icon('spark')}</div><span class="cover-note">把喜欢，写进每一次选择。</span></div></div><footer class="landing-footer"><span>与猫 AGENT · 互动恋爱故事</span><a href="gallery.html" target="_blank" rel="noopener">图文全集 ↗</a><button class="text-button" data-action="how">关于这段旅程</button></footer></section>`,'home');const collage=$('#cover-collage');if(!reduced()&&matchMedia('(pointer:fine)').matches)collage.addEventListener('pointermove',e=>{const r=collage.getBoundingClientRect();collage.style.setProperty('--px',((e.clientX-r.left)/r.width-.5)*2);collage.style.setProperty('--py',((e.clientY-r.top)/r.height-.5)*2)});}
function renderOnboarding(){const types=YumaoCompleteUI.types;mount(`<section class="onboarding page-enter"><div class="onboarding-art">${picture('q03-A',{eager:true,sizes:'(max-width:760px) 85vw, 45vw'})}<p>在别人的故事里，遇见自己的相处方式。</p></div><div class="onboarding-copy"><p class="eyebrow">BEFORE WE BEGIN</p><h1>故事开始前，<br>先认识一下你。</h1><p>你会在十二个情境中，为他们提供建议。<br>没有标准答案，选最接近你想法的那一个。</p><label class="type-label" for="initial-type">你原来的 MBTI</label><select class="type-select" id="initial-type"><option value="">先玩故事，结束时再填</option>${types.map(t=>`<option value="${t}"${t===state.initial?' selected':''}>${t}</option>`).join('')}</select><p class="small-note">用于结尾的四轴对比。暂时不知道，也可以先开始。<br>这是一次游戏中的相处探索。</p><button class="button-primary" data-action="begin">走进他们的故事${icon('arrow')}</button></div></section>`,'onboarding',{focus:true});}
