 mount(`<section class="game-shell page-enter" data-chapter="${q.displayId}" data-phase="${state.phase}">${progress(q)}<div class="scene-layout"><div class="theater"><div class="scene-art" id="scene-art"><div class="image-loading">${icon('cat')}</div>${picture(image,{eager:true})}<span class="scene-caption">${outcome?'AFTER YOUR CHOICE':'MOMENT '+pad(q.displayId)}</span><button class="icon-button art-button" data-action="art" data-image="${image}" aria-label="放大画面">${icon('expand')}</button></div><button class="dialogue-box" data-action="dialogue" aria-label="推进对白"><span class="speaker" id="speaker"></span><span class="speech-text" id="speech-text" aria-live="off"></span><span class="sr-only" id="speech-accessible"></span><span class="dialogue-hint" id="dialogue-hint"></span></button>${note?`<p class="theater-note">${esc(note)}</p>`:''}</div>${panel}</div><footer class="scene-footer"><span class="saved-state">${saveAvailable?'进度已保存 · 随时回来继续':'当前浏览器未能保存进度'}</span><span>第 ${q.displayId} 幕 / 共 12 幕</span><button data-action="chapters">章节目录 ↗</button></footer></section>`,'scene',{focus});
