function showDialogue(){clearTimeout(typingTimer);const item=dialogues[dialogueIndex];if(!item)return;$('#speaker').textContent=item.speaker;typingFull=item.text;$('#speech-accessible').textContent=item.text;$('#speech-text').textContent='';$('#speech-text').setAttribute('aria-hidden','true');$('#speech-text').classList.add('typing');typing=true;const token=renderToken;let index=0;const chars=[...item.text];function step(){if(token!==renderToken||screen!=='scene')return;index=Math.min(index+1,chars.length);$('#speech-text').textContent=chars.slice(0,index).join('');if(index<chars.length){typingTimer=setTimeout(step,/[，。！？…]/.test(chars[index-1])?100:25)}else finishTyping()}if(reduced())finishTyping();else step();setDialogueHint();}
