function renderEnding(){state.ended=true;persist();sound('ending');mount(`<section class="ending page-enter"><p class="eyebrow">TWELVE MOMENTS · ONE JOURNEY</p><h1>故事暂时落笔，<br>关于你的答案，刚刚浮现。</h1><p class="ending-lead">十二次选择，十二幕由你走过的故事。<br>有心动，有磨合，也有认真想过的未来。</p><div class="memory-wall">${D.questions.map((q,i)=>{const o=getOption(q);return `<figure class="memory-card" style="--rot:${[-4,2,-2,3,-3,4][i%6]}deg;--i:${i}">${picture(`q${pad(q.displayId)}-${o.id}`,{sizes:'(max-width:760px) 30vw, 17vw'})}<figcaption>${pad(q.displayId)} / ${o.id}</figcaption></figure>`}).join('')}</div><p class="ending-last">在他们的故事里，看见你的相处方式</p><button class="button-primary" data-action="report">打开我的恋爱报告${icon('arrow')}</button><p class="small-note">四轴对比 · 爱情风格称号 · 可保存的分享卡</p></section>`,'ending',{focus:true});}
