modal.addEventListener('close',()=>document.body.classList.remove('modal-open'));artModal.addEventListener('close',()=>{document.body.classList.remove('modal-open');$('#art-full').removeAttribute('src')});for(const d of [modal,artModal])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
